INSERT INTO `hrm_salary_slip_template` VALUES (1,'默认工资条模板',_binary '\0',_binary '','[{\"code\": 10101, \"name\": \"基本工资\", \"sort\": 10101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 10102, \"name\": \"岗位工资\", \"sort\": 10102, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 210101, \"name\": \"应发工资\", \"sort\": 210101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 230101, \"name\": \"个人所得税\", \"sort\": 230101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 240101, \"name\": \"实发工资\", \"sort\": 240101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}]','admin','2026-07-11 15:45:40','admin','2026-07-27 08:53:19',_binary '\0',0),(2,'默认工资条模板',_binary '\0',_binary '','[{\"code\": 10101, \"name\": \"基本工资\", \"sort\": 10101, \"type\": 2, \"hidden\": false, \"remark\": \"劳动合同中约定的标准工资。\", \"children\": []}, {\"code\": 10102, \"name\": \"岗位工资\", \"sort\": 10102, \"type\": 2, \"hidden\": false, \"remark\": \"根据岗位、责任、技能要求等，不同岗位，工资不同。\", \"children\": []}, {\"code\": 210101, \"name\": \"应发工资\", \"sort\": 210101, \"type\": 2, \"hidden\": false, \"remark\": \"应发工资=员工工资总额-请假扣款-考勤扣款等\", \"children\": []}, {\"code\": 230101, \"name\": \"个人所得税\", \"sort\": 230101, \"type\": 2, \"hidden\": false, \"remark\": \"根据个税计算规则，计算的每月应缴纳个税\", \"children\": []}, {\"code\": 240101, \"name\": \"实发工资\", \"sort\": 240101, \"type\": 2, \"hidden\": false, \"remark\": \"员工每月获得的实际收入。\", \"children\": []}]','1','2026-07-27 18:43:58','1','2026-07-27 18:43:58',_binary '\0',1),(3,'UI自动化工资条模板-0730-编辑',_binary '\0',_binary '\0','[{\"code\": 240, \"name\": \"实发工资\", \"sort\": 1, \"type\": 1, \"hidden\": false, \"remark\": null, \"children\": [{\"code\": 240101, \"name\": \"实发工资\", \"sort\": 2, \"type\": 2, \"hidden\": false, \"remark\": null, \"children\": []}]}, {\"code\": -1, \"name\": \"未分类科目\", \"sort\": 3, \"type\": 1, \"hidden\": false, \"remark\": null, \"children\": [{\"code\": 10101, \"name\": \"基本工资\", \"sort\": 4, \"type\": 2, \"hidden\": false, \"remark\": \"劳动合同中约定的标准工资。\", \"children\": []}, {\"code\": 10102, \"name\": \"岗位工资\", \"sort\": 5, \"type\": 2, \"hidden\": false, \"remark\": \"根据岗位、责任、技能要求等，不同岗位，工资不同。\", \"children\": []}, {\"code\": 10103, \"name\": \"职务工资\", \"sort\": 6, \"type\": 2, \"hidden\": false, \"remark\": \"根据职务高低、业务技术水平等因素的不同，工资不同，随职务变动而变动。\", \"children\": []}, {\"code\": 20101, \"name\": \"住房补贴\", \"sort\": 7, \"type\": 2, \"hidden\": false, \"remark\": \"为职工解决住房问题而给予的补贴资助。\", \"children\": []}, {\"code\": 20102, \"name\": \"高温津贴\", \"sort\": 8, \"type\": 2, \"hidden\": false, \"remark\": \"用人单位安排劳动者在高温天气下工作，当温度高于33℃，应支付高温补贴。\", \"children\": []}, {\"code\": 20103, \"name\": \"交通补贴\", \"sort\": 9, \"type\": 2, \"hidden\": false, \"remark\": \"企业按月按标准支付的交通补贴\", \"children\": []}, {\"code\": 20104, \"name\": \"餐补\", \"sort\": 10, \"type\": 2, \"hidden\": false, \"remark\": \"企业不统一供餐，而是按月按标准支付的午饭或晚餐补贴\", \"children\": []}, {\"code\": 30101, \"name\": \"绩效工资\", \"sort\": 11, \"type\": 2, \"hidden\": false, \"remark\": \"以员工的实际劳动成果或表现为考核标准，支付一定的奖励工资。\", \"children\": []}, {\"code\": 40101, \"name\": \"季度奖\", \"sort\": 12, \"type\": 2, \"hidden\": false, \"remark\": \"对于表现优秀的员工，按季度给予一定的奖励工资。\", \"children\": []}, {\"code\": 40102, \"name\": \"全勤奖\", \"sort\": 13, \"type\": 2, \"hidden\": false, \"remark\": \"对于按公司规定到岗工作，未出现任何迟到、早退的员工给予的奖励，一般以月度为考核期限。\", \"children\": []}, {\"code\": 40103, \"name\": \"推荐奖\", \"sort\": 14, \"type\": 2, \"hidden\": false, \"remark\": \"企业在招揽人才的过程中，对推荐人才并顺利入职的内部员工，给予的奖励工资。\", \"children\": []}, {\"code\": 50101, \"name\": \"销售提成\", \"sort\": 15, \"type\": 2, \"hidden\": false, \"remark\": \"对于销售或业务人员，通常按照一定的比例，企业和员工之间对盈利进行分成。\", \"children\": []}, {\"code\": 60101, \"name\": \"计件工资\", \"sort\": 16, \"type\": 2, \"hidden\": false, \"remark\": \"根据职工完成的劳动数量和按事先规定的计件单价计算和支付的工资。\", \"children\": []}, {\"code\": 70101, \"name\": \"计时工资\", \"sort\": 17, \"type\": 2, \"hidden\": fal