INSERT INTO `mes_dv_subject` VALUES (1,'CHK001','注塑机外观检查',1,'检查注塑机外壳是否有裂纹、变形、漏油等异常','外观完好，无明显损伤',0,'','1','2022-06-16 20:30:00','1','2026-02-20 01:49:32',_binary '\0',1),(2,'CHK002','电气线路点检',1,'检查设备电气线路连接是否牢固，有无破损老化','线路连接正常，无裸露铜线',0,'','1','2022-06-16 20:31:00','1','2026-02-20 01:49:32',_binary '\0',1),(3,'CHK003','安全防护装置检查',1,'检查设备安全门、急停按钮、防护罩等安全装置是否正常','安全装置功能正常，无失效',0,'','1','2022-06-16 20:32:00','1','2026-02-20 01:49:32',_binary '\0',1),(4,'CHK004','润滑系统点检',1,'检查润滑油位、油质、油路是否通畅','油位在标准范围内，油质清澈',0,'','1','2022-06-16 20:33:00','1','2026-02-20 01:49:32',_binary '\0',1),(5,'MNT001','注塑机润滑保养',2,'对注塑机各润滑点进行加油保养，更换润滑油','按照设备手册规定的润滑周期和油品进行保养',0,'','1','2022-06-16 20:34:00','1','2026-02-20 01:49:32',_binary '\0',1),(6,'MNT002','液压系统保养',2,'清洗液压过滤器，检查并补充液压油，检测系统压力','液压油清洁度达标，系统压力在正常范围',0,'','1','2022-06-16 20:35:00','1','2026-02-20 01:49:32',_binary '\0',1),(7,'MNT003','电气系统保养',2,'清洁电控柜，紧固接线端子，检查散热风扇','电控柜内无灰尘积累，接线端子紧固',0,'','1','2022-06-16 20:36:00','1','2026-02-20 01:49:32',_binary '\0',1),(8,'CHK005','温度检测点检',1,'检测设备关键部位温度是否在正常范围','温度不超过设备规定的最高值',1,'已停用','1','2022-06-16 20:37:00','1','2026-02-20 01:49:32',_binary '\0',1);
